-- name: ListPrevMonthSales :many
SELECT t2.sales_date, t2.amount, t2.discount
FROM (
    SELECT t1.sales_date AS sales_date, t1.amount AS amount, t1.discount AS discount
    FROM daily_sales AS t1
    WHERE (t1.store_code = sqlc.arg(store_code)::int4)
      AND (t1.sales_date <= ((date_trunc('month', (sqlc.arg(base_date)::date)::timestamp)::date) + (-1)))
      AND (t1.sales_date >= (date_trunc('month', (((sqlc.arg(base_date)::date + make_interval(months => (-1)))::date))::timestamp)::date))
) AS t2
ORDER BY t2.sales_date
LIMIT 32;
